import React from 'react';
import { Link } from 'react-router-dom';

const styles = {
  footer: {
    backgroundColor: '#2d3748',
    color: '#a0aec0',
    padding: '24px',
    textAlign: 'center',
  },
  container: {
    maxWidth: '1200px',
    margin: '0 auto',
  },
  nav: {
    marginBottom: '16px',
  },
  footerLink: {
    color: '#a0aec0',
    textDecoration: 'none',
    margin: '0 12px',
  },
  copyright: {
    marginTop: '16px',
    fontSize: '0.9rem',
  }
};

const Footer = () => {
  return (
    <footer style={styles.footer}>
      <div style={styles.container}>
        <nav style={styles.nav}>
          <Link to="/" style={styles.footerLink}>Home</Link>
          <a href="/#about" style={styles.footerLink}>About Us</a>
          <a href="/#services" style={styles.footerLink}>Services</a>
          <a href="/#contact" style={styles.footerLink}>Contact Us</a>
          <Link to="/terms" style={styles.footerLink}>Terms and Conditions</Link>
        </nav>
        <p style={styles.copyright}>
          &copy; {new Date().getFullYear()} Karpagam Clinic. All Rights Reserved.
        </p>
      </div>
    </footer>
  );
};

export default Footer;
